import { setTimeout as sleep } from 'node:timers/promises';
import { formatLogEntry } from '../display/logs-formatting.js';
import { runCommand } from '../package-manager.js';
import { createHintCollector } from './hints.js';
const envMs = (value, fallback) => {
    if (!value)
        return fallback;
    const parsed = Number(value);
    return Number.isFinite(parsed) && parsed >= 0 ? parsed : fallback;
};
/** Delay before the first operation poll. Override with SANITY_OPERATION_POLL_INITIAL_DELAY_MS. */
export const OPERATION_POLL_INITIAL_DELAY_MS = envMs(process.env.SANITY_OPERATION_POLL_INITIAL_DELAY_MS, 1000);
/** Interval between operation status polls. Override with SANITY_OPERATION_POLL_INTERVAL_MS. */
export const OPERATION_POLL_INTERVAL_MS = envMs(process.env.SANITY_OPERATION_POLL_INTERVAL_MS, 1500);
/** Consecutive failed polls tolerated before giving up on confirming status. */
export const OPERATION_POLL_MAX_CONSECUTIVE_ERRORS = 5;
const IDLE_SPINNER_DELAY_MS = 30_000;
const IDLE_SPINNER_UPDATE_INTERVAL_MS = 15_000;
export function createWaitFor({ bin, log, verbose, initialDelayMs = OPERATION_POLL_INITIAL_DELAY_MS, pollIntervalMs = OPERATION_POLL_INTERVAL_MS, idleSpinnerDelayMs = IDLE_SPINNER_DELAY_MS, }) {
    return async (options) => {
        const logHints = createHintCollector(bin);
        let logStreamCleanup = null;
        let idleSpinner;
        const stopIdleSpinner = (restoreOperationProgress = false) => {
            if (!idleSpinner)
                return;
            idleSpinner.stop();
            idleSpinner = undefined;
            if (restoreOperationProgress)
                log.showProgress();
        };
        try {
            log.showProgress();
            let lastLogAt = Date.now();
            let nextIdleSpinnerUpdateAt = idleSpinnerDelayMs;
            let consecutiveErrors = 0;
            let lastStatus;
            logStreamCleanup = options.onStartLogPolling({
                onActivity: () => {
                    lastLogAt = Date.now();
                    nextIdleSpinnerUpdateAt = idleSpinnerDelayMs;
                    stopIdleSpinner(true);
                },
                onLogEntry: (logEntry, previousLog) => {
                    logHints.inspectLog(logEntry);
                    log(formatLogEntry(logEntry, verbose, previousLog));
                },
            });
            // balk in case read replica lags
            await sleep(initialDelayMs);
            while (true) {
                const stateInfo = await options.onRequestLatestState();
                if (stateInfo.state === 'completed') {
                    if (logStreamCleanup)
                        logStreamCleanup();
                    stopIdleSpinner();
                    log('');
                    return { type: 'completed' };
                }
                if (stateInfo.state === 'failed') {
                    if (logStreamCleanup)
                        logStreamCleanup();
                    stopIdleSpinner();
                    log('');
                    return { type: 'failed', logHints: logHints.getSuggestions() };
                }
                // tolerate a few consecutive errors; the operation was accepted and may still be running
                if (stateInfo.state === 'error') {
                    consecutiveErrors += 1;
                    log.verbose(`${stateInfo.verboseError}; retrying (${consecutiveErrors}/${OPERATION_POLL_MAX_CONSECUTIVE_ERRORS}).`);
                    if (consecutiveErrors >= OPERATION_POLL_MAX_CONSECUTIVE_ERRORS) {
                        if (logStreamCleanup)
                            logStreamCleanup();
                        stopIdleSpinner();
                        log('');
                        return { type: 'unconfirmed', error: stateInfo.error ?? undefined };
                    }
                }
                else {
                    consecutiveErrors = 0;
                    if (stateInfo.state === 'not_found') {
                        log.verbose(stateInfo.verboseError);
                    }
                    else if (stateInfo.state === 'pending' && stateInfo.latestStatus !== lastStatus) {
                        log.verbose(stateInfo.verboseMessage);
                        lastStatus = stateInfo.latestStatus;
                    }
                }
                const idleFor = Date.now() - lastLogAt;
                if (idleFor >= nextIdleSpinnerUpdateAt) {
                    const elapsedIdleMs = idleSpinnerDelayMs +
                        Math.floor((idleFor - idleSpinnerDelayMs) / IDLE_SPINNER_UPDATE_INTERVAL_MS) *
                            IDLE_SPINNER_UPDATE_INTERVAL_MS;
                    const elapsedIdleSeconds = elapsedIdleMs / 1000;
                    const text = `No new activity for ${elapsedIdleSeconds} seconds. ${options.getIdleMessage()} You can safely exit and check status later with \`${runCommand(bin)} blueprints info\`.`;
                    if (idleSpinner)
                        idleSpinner.start(text);
                    else
                        idleSpinner = log.ora(text).start();
                    nextIdleSpinnerUpdateAt = elapsedIdleMs + IDLE_SPINNER_UPDATE_INTERVAL_MS;
                }
                await sleep(pollIntervalMs);
            }
        }
        catch (error) {
            if (logStreamCleanup)
                logStreamCleanup();
            throw error;
        }
        finally {
            stopIdleSpinner();
            log.clearProgress();
        }
    };
}
